INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'integrity', 'n.', '/ɪnˈteɡrɪti/', '正直;诚实', 'Growing up, I learned that integrity means doing the right thing even when no one is watching.', '在成长过程中,我懂得正直就是即使无人在看也做对的事。', 'Growing Up', 1, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a person of integrity', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'virtue', 'n.', '/ˈvɜːtʃuː/', '美德;优点', 'Patience is a virtue that we slowly develop as we grow up.', '耐心是一种我们在成长中慢慢培养的美德。', 'Growing Up', 2, 0, 'senior', 'wordlist', 'elective2', 'U1', 'patience is a virtue', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'licence', 'n.', '/ˈlaɪs(ə)ns/', '执照;许可证', 'When I turn 18, I can finally apply for a driving licence.', '等我满18岁,终于可以申请驾照了。', 'Growing Up', 3, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a driving licence', '美式拼 license;美音 /ˈlaɪsns/', 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'loan', 'n.', '/ləʊn/', '贷款;借款', 'He took out a bank loan to pay for his very first apartment.', '他申请了一笔银行贷款来支付自己的第一套公寓。', 'Growing Up', 4, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a bank loan', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'election', 'n.', '/ɪˈlekʃ(ə)n/', '选举', 'Once you reach the right age, you can vote in a general election.', '一旦到了规定年龄,你就能在大选中投票。', 'Growing Up', 5, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a general election', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'wage', 'n.', '/weɪdʒ/', '工资;薪金', 'Now that I earn a wage of my own, I have learned to budget carefully.', '如今我有了自己的工资,学会了精打细算。', 'Growing Up', 6, 0, 'senior', 'wordlist', 'elective2', 'U1', 'earn a wage', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'tax', 'n.', '/tæks/', '税;税款', 'Adults who earn a wage are expected to pay tax to the government.', '有收入的成年人都要向政府纳税。', 'Growing Up', 7, 0, 'senior', 'wordlist', 'elective2', 'U1', 'pay tax', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'ambulance', 'n.', '/ˈæmbjʊləns/', '救护车', 'Her mother is an ambulance driver and has seen many road accidents.', '她妈妈是救护车司机,目睹过许多交通事故。', 'Growing Up', 8, 0, 'senior', 'wordlist', 'elective2', 'U1', 'an ambulance driver', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'legal', 'adj.', '/ˈliːɡ(ə)l/', '合法的;法律的', 'Eighteen is the legal age for getting a driving licence in many countries.', '在很多国家,18岁是领取驾照的法定年龄。', 'Growing Up', 9, 0, 'senior', 'wordlist', 'elective2', 'U1', 'the legal age', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'mature', 'adj.', '/məˈtʃʊə/', '成熟的;明白事理的', 'I believe I am mature enough to take responsibility for my own life.', '我相信自己已足够成熟,能为自己的人生负责。', 'Growing Up', 10, 0, 'senior', 'wordlist', 'elective2', 'U1', 'mature enough', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'instantly', 'adv.', '/ˈɪnstəntli/', '立即;马上', 'I expected to feel instantly different on my eighteenth birthday.', '我以为18岁生日那天会立刻感到不一样。', 'Growing Up', 11, 0, 'senior', 'wordlist', 'elective2', 'U1', 'change instantly', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'gradual', 'adj.', '/ˈɡrædʒuəl/', '逐渐的;逐步的', 'Growing up is a gradual change rather than a sudden one.', '成长是一种逐渐的变化,而非突然的转变。', 'Growing Up', 12, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a gradual change', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'approve', 'v.', '/əˈpruːv/', '赞成;同意;批准', 'I made the decision on my own, though I knew my parents would approve.', '这个决定是我独自做的,尽管我知道父母会赞成。', 'Growing Up', 13, 0, 'senior', 'wordlist', 'elective2', 'U1', 'approve of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'librarian', 'n.', '/laɪˈbreəriən/', '图书馆管理员', 'On a librarian''s salary, Morgan still lives at home with his parents.', '靠图书管理员的工资,摩根仍和父母住在家里。', 'Growing Up', 14, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a librarian''s salary', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'household', 'adj.', '/ˈhaʊshəʊld/', '家庭的;家用的', 'Now that I work, I help to pay the household bills every month.', '如今我工作了,每月都帮忙支付家庭账单。', 'Growing Up', 15, 0, 'senior', 'wordlist', 'elective2', 'U1', 'household bills', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'commitment', 'n.', '/kəˈmɪtmənt/', '承诺;投入;责任', 'Renting a flat is a big commitment that I do not feel ready to make.', '租房是一项重大的承诺,我还没准备好。', 'Growing Up', 16, 0, 'senior', 'wordlist', 'elective2', 'U1', 'make a commitment', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'suitable', 'adj.', '/ˈsuːtəb(ə)l/', '合适的;适当的', 'Choose a suitable title for the passage about turning eighteen.', '为这篇关于年满18岁的文章选一个合适的标题。', 'Growing Up', 17, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a suitable title', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'minimum', 'adj.', '/ˈmɪnɪməm/', '最小的;最低的', 'Do you think the minimum age limits for voting are sensible?', '你认为投票的最低年龄限制合理吗?', 'Growing Up', 18, 0, 'senior', 'wordlist', 'elective2', 'U1', 'the minimum age', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'varied', 'adj.', '/ˈveərid/', '各种各样的;多变的', 'As life goes on, we are offered more and more varied experiences.', '随着生活继续,我们会遇到越来越多样的经历。', 'Growing Up', 19, 0, 'senior', 'wordlist', 'elective2', 'U1', 'varied experiences', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'routine', 'n.', '/ruːˈtiːn/', '惯例;日常;常规', 'Living away from home, I had to get used to a brand-new daily routine.', '离家生活后,我不得不适应全新的日常作息。', 'Growing Up', 20, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a daily routine', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'chew', 'v.', '/tʃuː/', '咀嚼;嚼', 'A boa constrictor swallows its food whole and does not chew it at all.', '蟒蛇把食物整个吞下,根本不咀嚼。', 'Growing Up', 21, 0, 'senior', 'wordlist', 'elective2', 'U1', 'chew food', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'digestion', 'n.', '/daɪˈdʒestʃ(ə)n/', '消化(过程)', 'After a huge meal, the snake sleeps for months during digestion.', '饱餐一顿后,蟒蛇在消化期间会睡上好几个月。', 'Growing Up', 22, 0, 'senior', 'wordlist', 'elective2', 'U1', 'aid digestion', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'digest', 'v.', '/daɪˈdʒest/', '消化(食物)', 'It takes the snake six months to digest such a large animal.', '蟒蛇要花六个月才能消化掉这么大的动物。', 'Growing Up', 23, 0, 'senior', 'wordlist', 'elective2', 'U1', 'digest food', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'consequence', 'n.', '/ˈkɒnsɪkwəns/', '后果;结果', 'The grown-ups were always concerned with matters of consequence.', '大人们总是只关心要紧的事。', 'Growing Up', 24, 0, 'senior', 'wordlist', 'elective2', 'U1', 'matters of consequence', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'evidence', 'n.', '/ˈevɪd(ə)ns/', '证据;依据', 'Find evidence in the passage to support the author''s attitude to grown-ups.', '在文中找出证据来支持作者对大人的看法。', 'Growing Up', 25, 0, 'senior', 'wordlist', 'elective2', 'U1', 'find evidence', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'politics', 'n.', '/ˈpɒlɪtɪks/', '政治', 'The grown-up only wanted to talk about golf and politics.', '那个大人只想聊高尔夫和政治。', 'Growing Up', 26, 0, 'senior', 'wordlist', 'elective2', 'U1', 'talk about politics', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'golf', 'n.', '/ɡɒlf/', '高尔夫球运动', 'He brought himself down to their level and chatted about golf and ties.', '他迁就他们的水平,聊起了高尔夫和领带。', 'Growing Up', 27, 0, 'senior', 'wordlist', 'elective2', 'U1', 'play golf', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'airline', 'n.', '/ˈeəlaɪn/', '航空公司', 'Fine, don''t buy me an airline ticket — I''ll just swim across the ocean!', '行,别给我买机票了——我游过大洋去好了!', 'Growing Up', 28, 0, 'senior', 'wordlist', 'elective2', 'U1', 'an airline ticket', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'bond', 'n.', '/bɒnd/', '纽带;关系;联系', 'We form special bonds with others by caring for them and taking responsibility.', '我们通过关心他人、承担责任而与他人建立特殊的纽带。', 'Growing Up', 29, 0, 'senior', 'wordlist', 'elective2', 'U1', 'form a bond', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'conclusion', 'n.', '/kənˈkluːʒ(ə)n/', '结论;结尾', 'In the conclusion of his review, he recommends the book to readers of every age.', '在书评的结尾,他把这本书推荐给各个年龄段的读者。', 'Growing Up', 30, 0, 'senior', 'wordlist', 'elective2', 'U1', 'reach a conclusion', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'adulthood', 'n.', '/ˈædʌlthʊd/', '成年', 'In most countries, turning eighteen marks the start of adulthood.', '在大多数国家,年满18岁标志着成年的开始。', 'Growing Up', 31, 0, 'senior', 'wordlist', 'elective2', 'U1', 'the start of adulthood', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'milestone', 'n.', '/ˈmaɪlstəʊn/', '重大事件;里程碑', 'Reaching this milestone, the age of majority, brings new responsibilities.', '到达这一里程碑——成年——会带来新的责任。', 'Growing Up', 32, 0, 'senior', 'wordlist', 'elective2', 'U1', 'reach a milestone', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'childhood', 'n.', '/ˈtʃaɪldhʊd/', '童年;儿童时代', 'On that day I felt as if I had closed the door on my childhood.', '那天我感觉自己仿佛关上了通往童年的门。', 'Growing Up', 33, 0, 'senior', 'wordlist', 'elective2', 'U1', 'leave childhood behind', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'obey', 'v.', '/əʊˈbeɪ/', '服从;遵守', 'Even after turning eighteen, there were still rules to obey.', '即便满了18岁,仍有规则要遵守。', 'Growing Up', 34, 0, 'senior', 'wordlist', 'elective2', 'U1', 'obey the rules', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'subtle', 'adj.', '/ˈsʌtl/', '微妙的;难以察觉的', 'The change has been more subtle and gradual than I had imagined.', '这种变化比我想象的更微妙、更循序渐进。', 'Growing Up', 35, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a subtle change', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'selfish', 'adj.', '/ˈselfɪʃ/', '自私的', 'Instead of being the selfish teenager I used to be, I now think of others.', '我不再是从前那个自私的少年,如今会替别人着想。', 'Growing Up', 36, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a selfish teenager', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'steady', 'adj.', '/ˈstedi/', '稳定的;平稳的', 'I don''t have a steady income yet, so a credit card could be risky.', '我还没有稳定的收入,所以信用卡可能有风险。', 'Growing Up', 37, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a steady income', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'tempt', 'v.', '/tempt/', '诱惑;引诱', 'A credit card might tempt me to spend more money than I really have.', '信用卡可能会诱惑我花掉超过自己所有的钱。', 'Growing Up', 38, 0, 'senior', 'wordlist', 'elective2', 'U1', 'tempt sb to do', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'commute', 'n.', '/kəˈmjuːt/', '上下班的路程;通勤', 'Because my commute to work is expensive, I find it hard to save money.', '由于上班的路程花费很高,我很难存下钱。', 'Growing Up', 39, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a long commute', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'deposit', 'n.', '/dɪˈpɒzɪt/', '订金;押金', 'I could get a loan to pay the deposit on my very own apartment.', '我可以贷款来支付自己公寓的押金。', 'Growing Up', 40, 0, 'senior', 'wordlist', 'elective2', 'U1', 'pay the deposit', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'cherish', 'v.', '/ˈtʃerɪʃ/', '珍视;珍惜', 'Whatever our choices are, we should cherish these moments in life.', '无论我们做什么选择,都应珍惜生命中的这些时刻。', 'Growing Up', 41, 0, 'senior', 'wordlist', 'elective2', 'U1', 'cherish a moment', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'memorable', 'adj.', '/ˈmem(ə)rəb(ə)l/', '难忘的;值得纪念的', 'Share a most memorable moment from your life with your partner.', '和同伴分享你生命中最难忘的一个时刻。', 'Growing Up', 42, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a memorable moment', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'bittersweet', 'adj.', '/ˌbɪtəˈswiːt/', '苦乐参半的', 'Some moments of growing up are bittersweet, both happy and a little sad.', '成长中的有些时刻是苦乐参半的,既快乐又略带伤感。', 'Growing Up', 43, 0, 'senior', 'wordlist', 'elective2', 'U1', 'a bittersweet moment', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'swallow', 'v.', '/ˈswɒləʊ/', '吞下;咽下', 'A boa constrictor can swallow a small animal whole.', '蟒蛇能把一只小动物整个吞下。', 'Growing Up', 44, 0, 'senior', 'wordlist', 'elective2', 'U1', 'swallow whole', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'prey', 'n.', '/preɪ/', '猎物', 'The snake swallows its prey without chewing it first.', '蟒蛇不先咀嚼就把猎物吞下。', 'Growing Up', 45, 0, 'senior', 'wordlist', 'elective2', 'U1', 'swallow its prey', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'masterpiece', 'n.', '/ˈmɑːstəpiːs/', '杰作;代表作', 'As a child, the author proudly showed his masterpiece to the grown-ups.', '作者小时候曾自豪地把自己的杰作拿给大人看。', 'Growing Up', 46, 0, 'senior', 'wordlist', 'elective2', 'U1', 'show one''s masterpiece', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'ponder', 'v.', '/ˈpɒndə/', '仔细考虑;深思', 'As a boy he would ponder deeply over the adventures of the jungle.', '小时候,他会对丛林历险深深地思索。', 'Growing Up', 47, 0, 'senior', 'wordlist', 'elective2', 'U1', 'ponder over', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'necktie', 'n.', '/ˈnektaɪ/', '领带', 'The grown-ups only wanted to talk about golf and neckties.', '大人们只想谈论高尔夫和领带。', 'Growing Up', 48, 0, 'senior', 'wordlist', 'elective2', 'U1', 'wear a necktie', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe2u1.01', '①将来进行时表将来某一时刻正在进行的动作', 'A2', 11, '外研社版选择性必修第二册 U1 — 句中有 this time tomorrow / at 8 tonight / while you are… 等"将来某一点"或"同时进行"标志时,表示那一刻"正在进行"的持续性动作,用 will be doing(而非一次性完成的 will do)。', 1, 'elective2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe2u1.02', '②将来进行时 vs 一般将来时(进行中 vs 整体完成)', 'A2', 11, '外研社版选择性必修第二册 U1 — 强调将来某时"正进行/作背景"的持续动作用 will be doing;表示"承诺/决定/条件结果/一次性完成"的整体动作用 will do。由语境判断填哪一种。', 2, 'elective2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe2u1.03', '③将来进行时表委婉询问 / 预期中自然发生的将来', 'A2', 11, '外研社版选择性必修第二册 U1 — 用 Will you be doing…? 礼貌、客观地询问对方既定安排(不含请求/施压);用 I''ll be doing… 表示"按常规、顺理成章"会发生的将来,而非临时的意愿或决定。', 3, 'elective2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"This time tomorrow, I ____ my driving test, so please wish me luck!"', 'will be taking', 'will take', 'take', 'took', 'A', 'this time tomorrow 指将来某一时刻、考试正在进行 → will be taking。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"Don''t call me at eight tonight — I ____ dinner with my family then."', 'will have', 'will be having', 'have', 'had', 'B', 'at eight tonight 那一刻正在吃饭,持续动作 → will be having。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"While you are lying on the beach next week, I ____ hard for my final exams."', 'will study', 'study', 'will be studying', 'studied', 'C', 'while you are lying… 表两动作同时进行 → will be studying。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"At noon tomorrow, the new graduates ____ across the stage to collect their certificates."', 'will walk', 'walk', 'walked', 'will be walking', 'D', 'at noon tomorrow 那一刻正走过舞台 → will be walking。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"This time next year, I ____ at a university far away from home."', 'will be studying', 'will study', 'am studying', 'studied', 'A', 'this time next year 指将来某点正在进行 → will be studying。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"At ten o''clock tonight, the night train ____ us towards the capital."', 'will carry', 'will be carrying', 'carries', 'carried', 'B', 'at ten tonight 那一刻列车正载着我们 → will be carrying。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"When you arrive at the airport tomorrow, I ____ for you near the gate."', 'will wait', 'wait', 'will be waiting', 'waited', 'C', 'when you arrive 那一刻我正在等 → will be waiting。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"This time tomorrow morning, the whole class ____ their final exam papers."', 'will write', 'write', 'wrote', 'will be writing', 'D', 'this time tomorrow morning 那一刻正在写 → will be writing。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"At this moment next week, we ____ over the Pacific on our way to Australia."', 'will be flying', 'will fly', 'fly', 'flew', 'A', 'at this moment next week 那一刻正在飞行 → will be flying。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"Don''t visit me at three this afternoon — I ____ a nap after the long journey."', 'will have', 'will be having', 'have', 'had', 'B', 'at three 那一刻正在午睡 → will be having。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"While my parents are at work tomorrow, I ____ online for my own apartment."', 'will search', 'search', 'will be searching', 'searched', 'C', 'while my parents are at work 表同时进行 → will be searching。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"At eight tomorrow evening, she ____ her organ donation form at the hospital."', 'will sign', 'signs', 'signed', 'will be signing', 'D', 'at eight tomorrow evening 那一刻正在签 → will be signing。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"This time on Saturday, the volunteers ____ trees in the city park."', 'will be planting', 'will plant', 'plant', 'planted', 'A', 'this time on Saturday 那一刻正在植树 → will be planting。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"When the clock strikes midnight, we ____ in the New Year together."', 'will welcome', 'will be welcoming', 'welcome', 'welcomed', 'B', 'when the clock strikes midnight 那一刻正在迎接 → will be welcoming。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"At lunchtime tomorrow, the new librarian ____ books onto the shelves."', 'will arrange', 'arranges', 'will be arranging', 'arranged', 'C', 'at lunchtime tomorrow 那一刻正在整理 → will be arranging。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"While you are still sleeping, the early bus ____ me to my first day at work."', 'will take', 'takes', 'took', 'will be taking', 'D', 'while you are sleeping 表同时进行 → will be taking。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"This time tomorrow, the graduates ____ goodbye to the campus they love."', 'will be saying', 'will say', 'say', 'said', 'A', 'this time tomorrow 那一刻正在道别 → will be saying。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"At seven tonight, I ____ to my grandfather about my plans for the future."', 'will talk', 'will be talking', 'talk', 'talked', 'B', 'at seven tonight 那一刻正在交谈 → will be talking。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"When you wake up tomorrow, I ____ on a train towards my new job."', 'will travel', 'travel', 'will be travelling', 'travelled', 'C', 'when you wake up 那一刻我正在路上 → will be travelling。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.01'), '"At this time next month, he ____ in his very own rented flat."', 'will live', 'lives', 'lived', 'will be living', 'D', 'at this time next month 指将来某点持续居住 → will be living。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"Don''t phone me at nine tonight — I ____ my favourite show then."', 'will be watching', 'will watch', 'watch', 'watched', 'A', 'at nine then 那一刻正在看,强调进行 → will be watching。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"This time tomorrow we ____ for our final exams, so we really can''t meet up."', 'will revise', 'will be revising', 'revise', 'revised', 'B', 'this time tomorrow 那一刻正在复习 → will be revising。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"At six this evening the volunteers ____ the hall for the leavers'' party."', 'will decorate', 'decorate', 'will be decorating', 'decorated', 'C', 'at six this evening 那一刻正在布置,进行中 → will be decorating。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"While the others are sleeping, I ____ quietly in the library."', 'will study', 'study', 'studied', 'will be studying', 'D', 'while the others are sleeping 表同时进行 → will be studying。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"Don''t worry about me at noon — I ____ lunch with my new classmates then."', 'will be having', 'will have', 'have', 'had', 'A', 'at noon then 那一刻正在吃饭 → will be having。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"When you call at eight, the children ____ their homework upstairs."', 'will do', 'will be doing', 'do', 'did', 'B', 'when you call at eight 那一刻正在做作业 → will be doing。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"This time on Sunday, Grandpa ____ his calligraphy as he always does."', 'will practise', 'practises', 'will be practising', 'practised', 'C', 'this time on Sunday 那一刻正在练字 → will be practising。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"Don''t expect a quick reply at three — I ____ my driving test then."', 'will take', 'take', 'took', 'will be taking', 'D', 'at three then 那一刻正在考试 → will be taking。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"While you are at work, the movers ____ my things into the new flat."', 'will be carrying', 'will carry', 'carry', 'carried', 'A', 'while you are at work 表同时进行 → will be carrying。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"At this time tomorrow, the band ____ on the main stage of the festival."', 'will play', 'will be playing', 'plays', 'played', 'B', 'at this time tomorrow 那一刻正在演奏 → will be playing。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"I promise I ____ the household bills as soon as I get my first wage."', 'will be paying', 'pay', 'will pay', 'paid', 'C', 'I promise… 是承诺、一次性完成动作 → 一般将来 will pay。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"If you lend me the money now, I ____ it back to you next month."', 'will be giving', 'give', 'gave', 'will give', 'D', '条件句结果、整体完成的归还动作 → will give。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"The moment I turn eighteen, I ____ for a driving licence straight away."', 'will apply', 'will be applying', 'apply', 'applied', 'A', 'the moment… straight away 一次性完成的决定动作 → will apply。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"Don''t worry — I ____ you the moment I reach the dormitory tonight."', 'will be texting', 'will text', 'text', 'texted', 'B', 'the moment I reach… 一次性完成的动作 → will text。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"I''ve finally decided that next year I ____ an organ donation form."', 'will be signing', 'sign', 'will sign', 'signed', 'C', 'I''ve decided 表决定、整体完成的一次动作 → will sign。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"If it rains tomorrow, we ____ the graduation party indoors instead."', 'will be holding', 'hold', 'held', 'will hold', 'D', '条件句结果、整体安排 → will hold。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"She is certain that hard work ____ her dream come true one day."', 'will make', 'will be making', 'makes', 'made', 'A', '对结果的预测、整体完成 → will make。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"Give me one week, and I ____ back every cent that I borrowed."', 'will be paying', 'will pay', 'pay', 'paid', 'B', '承诺、一次性完成的归还 → will pay。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"Once the exams are over, I ____ a part-time job for the summer."', 'will be finding', 'find', 'will find', 'found', 'C', 'once… 表整体完成的将来动作 → will find。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.02'), '"I''m sure you ____ the right decision when the time finally comes."', 'will be making', 'make', 'made', 'will make', 'D', '对未来整体动作的预测 → will make。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"____ the computer this evening? If not, may I borrow it for my homework?"', 'Will you be using', 'Will you use', 'Do you use', 'Did you use', 'A', '委婉询问对方既定安排、不含请求 → Will you be using。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"____ past the post office on your way home? I just need one stamp."', 'Will you go', 'Will you be going', 'Do you go', 'Went you', 'B', '客观询问对方行程安排 → Will you be going。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"____ the car tomorrow, Dad? I''d like to drive to the library if it''s free."', 'Will you need', 'Do you need', 'Will you be needing', 'Needed you', 'C', '礼貌打听对方是否需要、不施压 → Will you be needing。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"____ in this seat much longer? I''m waiting for somewhere to sit."', 'Will you stay', 'Do you stay', 'Stayed you', 'Will you be staying', 'D', '委婉询问对方安排 → Will you be staying。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"____ to the graduation party on Friday? I can easily give you a lift."', 'Will you be coming', 'Will you come', 'Do you come', 'Came you', 'A', '客观询问对方计划 → Will you be coming。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"____ the photocopier for long? I have just a single page to print."', 'Will you use', 'Will you be using', 'Do you use', 'Used you', 'B', '礼貌询问对方占用安排 → Will you be using。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"____ your headphones tonight? I''d love to borrow them for the train."', 'Will you wear', 'Do you wear', 'Will you be wearing', 'Wore you', 'C', '委婉打听对方安排 → Will you be wearing。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"____ the kitchen soon? I''d like to start cooking dinner if you''ve finished."', 'Will you use', 'Do you use', 'Did you use', 'Will you be using', 'D', '客观询问对方占用计划 → Will you be using。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"____ at home this evening? I might drop by with the documents."', 'Will you be working', 'Will you work', 'Do you work', 'Worked you', 'A', '委婉询问对方既定安排 → Will you be working。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"____ the meeting room after lunch? Our study group needs a quiet space."', 'Will you use', 'Will you be using', 'Do you use', 'Use you', 'B', '礼貌打听对方安排 → Will you be using。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"I ____ Lin Ning at the library tomorrow anyway, so I''ll pass on your message."', 'will see', 'see', 'will be seeing', 'saw', 'C', 'anyway 表顺理成章会发生的将来,非临时意愿 → will be seeing。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"Don''t make a special trip — I ____ past your house this afternoon in any case."', 'will drive', 'drive', 'drove', 'will be driving', 'D', 'in any case 表本就会发生的将来 → will be driving。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"Ask Tom yourself; I ____ him at training later today as usual."', 'will be meeting', 'will meet', 'meet', 'met', 'A', 'as usual 表按常规自然会发生 → will be meeting。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"Leave the books with me — I ____ to the library tomorrow anyway."', 'will go', 'will be going', 'go', 'went', 'B', 'anyway 表本就要去 → will be going。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"There''s no need to wait up; we ____ home quite late after the ceremony."', 'will get', 'get', 'will be getting', 'got', 'C', '顺理成章会发生的将来情形 → will be getting。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"Don''t bother posting it; I ____ the office tomorrow and can hand it in myself."', 'will visit', 'visit', 'visited', 'will be visiting', 'D', '表本就安排好的将来行程 → will be visiting。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"I ____ my grandparents this weekend in any case, so I''ll deliver the gift."', 'will be visiting', 'will visit', 'visit', 'visited', 'A', 'in any case 表顺理成章的将来 → will be visiting。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"She ____ through the city centre on her way to work, so she can pick it up."', 'will pass', 'will be passing', 'passes', 'passed', 'B', '表本就会发生的将来情形 → will be passing。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"I ____ near the station later this evening, so I can easily collect your parcel."', 'will walk', 'walk', 'will be walking', 'walked', 'C', 'later 表顺路、自然会发生的将来 → will be walking。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U1' AND code='fe2u1.03'), '"We ____ dinner at six as usual, so do join us if you happen to be free."', 'will have', 'have', 'had', 'will be having', 'D', 'as usual 表按常规进行的将来情形 → will be having。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Age of Majority', 'In most countries, turning eighteen marks the start of adulthood. People often call this the age of majority. But what does reaching this milestone really mean? Many teenagers imagine that everything will change instantly, as if they have closed the door on childhood and stepped into a whole new adult world. The reality is usually different. The change is more subtle and gradual than people expect. When you wake up the morning after your birthday, there are still rules to obey and lessons to attend. What does change is the way society treats you. Suddenly you can vote in an election, sign important papers, and take responsibility for choices that were once made by your parents. With these new freedoms come new duties. Being eighteen does not mean you are fully grown overnight; it simply means you are trusted to begin making your own decisions, and to live with whatever follows from them.', '说明·成年的真正含义', 153, '[{"q":"What do many teenagers wrongly expect about turning eighteen?","answer":"A","options":["That their life will be transformed in an instant.","That they will lose the right to vote.","That nothing at all will ever change.","That their parents will make all decisions."],"explanation":"原文说青少年以为一切会 instantly 改变,而现实并非如此,选项为其转述。"},{"q":"According to the passage, how does growing up actually happen?","answer":"B","options":["Suddenly, overnight on the birthday.","Slowly and in ways hard to notice.","Only after one leaves the country.","Never, no matter how old you are."],"explanation":"原文 ''more subtle and gradual than people expect'' 的转述。"},{"q":"What does the writer say really comes with turning eighteen?","answer":"A","options":["Both new freedoms and new responsibilities.","Total freedom with no duties.","The end of all rules in life.","A guaranteed well-paid job."],"explanation":"末段说新自由伴随新责任,被信任开始自己做决定,为其概括。"}]'::jsonb, '[{"word":"adulthood","cn":"成年"},{"word":"milestone","cn":"里程碑"},{"word":"majority","cn":"(此处)成年"}]'::jsonb, 2, 'elective2', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'My First Driving Test', 'Bethany cannot wait to turn eighteen. Ever since leaving school she has been earning a wage, yet she still cannot vote in the next election because she is not quite old enough. She finds this unfair: if you are old enough to work and pay tax, she argues, you should have a say in how the government spends it. Bethany has also been taking driving lessons, and she plans to sit her driving test on the very day she turns eighteen. Her mother is worried. As an ambulance driver, her mum has seen many accidents involving young people, and she believes the legal age for a licence should be twenty-one. Bethany understands her mother''s fear, but she does not fully agree. To her, being behind the wheel is not only a freedom but also a serious duty. She feels mature enough to know that driving means caring for her own life and the lives of everyone else on the road.', '记叙·盼望考驾照', 160, '[{"q":"Why does Bethany feel the voting rule is unfair?","answer":"B","options":["Because she dislikes all elections.","Because she works and pays tax yet still cannot vote.","Because she has never had a job.","Because she is already over twenty-one."],"explanation":"原文 ''old enough to work and pay tax… should have a say'' 的转述。"},{"q":"Why is Bethany''s mother worried about her driving?","answer":"C","options":["She thinks Bethany cannot afford a car.","She wants Bethany to become an ambulance driver.","She has witnessed many crashes involving young drivers.","She believes driving is no longer useful."],"explanation":"原文母亲作为救护车司机见过许多涉及年轻人的事故,为其转述。"},{"q":"How does Bethany view being allowed to drive?","answer":"D","options":["As something completely without risk.","As a way to avoid paying tax.","As a hobby with no link to safety.","As a freedom that also brings real responsibility."],"explanation":"末段说开车既是自由也是认真负责的责任,为其概括。"}]'::jsonb, '[{"word":"wage","cn":"工资"},{"word":"ambulance","cn":"救护车"},{"word":"legal","cn":"合法的"}]'::jsonb, 2, 'elective2', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Still Living at Home', 'People say that eighteen begins a new chapter and that we should quickly become independent. Morgan used to believe this too. He assumed that as soon as he turned eighteen he would already have a well-paid job and be moving into a rented apartment of his own. Reality turned out to be quite different. His salary as a junior librarian is small, so for now he still lives at home with his parents. Because he helps with the household bills and his commute to work is expensive, he finds it hard to save any money at all. Morgan knows he could take out a bank loan to pay the deposit on a flat, but he does not feel ready to make that kind of commitment yet. Besides, he rather enjoys his mother''s cooking. Looking back, he has come to a quiet conclusion: some kinds of responsibility have far more to do with attitude than with a person''s age.', '记叙·成年后仍住在家', 158, '[{"q":"What had Morgan expected life at eighteen to be like?","answer":"A","options":["Having a good job and his own rented flat.","Living with his parents for many more years.","Earning nothing and studying full-time.","Travelling around the world alone."],"explanation":"原文他原以为会有高薪工作并搬进出租公寓,为其转述。"},{"q":"Why does Morgan find it hard to save money?","answer":"B","options":["He spends it all on holidays abroad.","He helps with bills and pays a costly commute.","He refuses to do any paid work.","He gives all his wage to charity."],"explanation":"原文他分担家庭账单、通勤又贵,为其转述。"},{"q":"What conclusion does Morgan finally reach?","answer":"C","options":["That money matters more than family.","That everyone should move out at eighteen.","That responsibility depends on attitude more than age.","That bank loans are always a mistake."],"explanation":"末句 ''more about attitude than age'' 的转述。"}]'::jsonb, '[{"word":"commute","cn":"通勤路程"},{"word":"deposit","cn":"押金"},{"word":"commitment","cn":"承诺"}]'::jsonb, 2, 'elective2', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Bittersweet Moments', 'Like a piece of music, life has its high notes and its low ones, and somewhere in between lie the moments we call bittersweet. For students, these moments often come from school life: sitting an important exam, giving a speech in front of the class, or becoming a boarder and living away from home for the very first time. Such experiences can feel both exciting and a little frightening. As we grow older, life offers us even more varied experiences. We start university, take our first job, and one day raise a family of our own. Each of these steps brings its own mix of joy and worry. Whatever choices we make along the way, we should learn to cherish and embrace these moments rather than rush past them. After all, every single step we take, however small, is one more step forward on the journey of becoming a stronger and better person.', '议论·珍惜成长中的时刻', 153, '[{"q":"What does the writer compare life to at the beginning?","answer":"D","options":["A long and difficult exam.","A race that must be won quickly.","A book that nobody reads.","A piece of music with high and low notes."],"explanation":"原文把生活比作有高低音的乐曲,为其转述。"},{"q":"Which of these is given as a bittersweet moment of school life?","answer":"A","options":["Living away from home as a boarder for the first time.","Buying a brand-new mobile phone.","Winning a large sum of money.","Watching television at the weekend."],"explanation":"原文列举 becoming a boarder 等校园时刻,为其转述。"},{"q":"What does the writer advise us to do with these moments?","answer":"B","options":["Forget them as fast as possible.","Value them instead of hurrying past.","Avoid them whenever we can.","Keep them secret from everyone."],"explanation":"原文劝我们 cherish and embrace 这些时刻,为其转述。"}]'::jsonb, '[{"word":"bittersweet","cn":"苦乐参半的"},{"word":"varied","cn":"各种各样的"},{"word":"cherish","cn":"珍视"}]'::jsonb, 2, 'elective2', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Money and Independence', 'One surprising part of turning eighteen is how differently society starts to treat you with money. Lin Ning was amazed when a bank contacted him with a credit card offer soon after his birthday. Of course, like most young people, he would enjoy having more freedom with money. Yet he knows he does not have a steady income, so a credit card might tempt him to spend far more than he actually has. Being trusted with money, he realised, is not the same as being ready for it. Real independence is not about how much you can borrow, but about how wisely you can plan. A loan can help you pay a deposit on a flat, but it also becomes a promise you must keep for years. Lin Ning has decided to wait. He would rather build good habits first, save a little each month, and only take on debt when he truly understands what it will cost him.', '说明·成年与金钱管理', 159, '[{"q":"Why might a credit card be risky for Lin Ning?","answer":"C","options":["It would force him to leave his job.","It is not accepted in any shop.","It could lead him to spend more than he can afford.","It must be paid back within one day."],"explanation":"原文说没有稳定收入,信用卡可能诱使他超支,为其转述。"},{"q":"What does Lin Ning believe real independence is about?","answer":"D","options":["Borrowing as much money as possible.","Owning the newest things first.","Never using a bank at all.","Planning your money wisely."],"explanation":"原文 ''about how wisely you can plan'' 的转述。"},{"q":"What has Lin Ning decided to do for now?","answer":"A","options":["Build good habits and save before borrowing.","Take the largest loan he can get.","Buy a flat immediately with a credit card.","Stop earning a wage completely."],"explanation":"末段说他决定先养成好习惯、每月存钱再借贷,为其概括。"}]'::jsonb, '[{"word":"steady","cn":"稳定的"},{"word":"tempt","cn":"诱惑"},{"word":"loan","cn":"贷款"}]'::jsonb, 2, 'elective2', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A Lesson in Integrity', 'When Daniel got his first part-time job at a small shop, he thought growing up just meant earning his own wage. One quiet afternoon, a customer paid for her shopping and left without taking her change. It was only a few coins, and no one had noticed. For a moment Daniel was tempted to slip the money into his own pocket. Then he remembered something his grandmother always said: integrity means doing the right thing even when nobody is watching. He ran out of the shop and returned the change to the surprised customer. She thanked him warmly and later told his manager how honest he had been. That evening Daniel felt prouder than he had ever felt about any wage. He understood that becoming an adult was not only about new freedoms or money. It was also about the quiet, everyday choices that slowly shape the kind of person you decide to be.', '记叙·成长与正直', 154, '[{"q":"What did Daniel first think growing up was mainly about?","answer":"B","options":["Travelling far from home.","Earning money of his own.","Passing his driving test.","Living completely alone."],"explanation":"原文他起初以为长大就是赚自己的工资,为其转述。"},{"q":"What did Daniel finally do about the customer''s change?","answer":"C","options":["He quietly kept the coins for himself.","He handed it to another customer.","He gave the money back to her.","He left it lying on the counter."],"explanation":"原文他追出去把零钱还给顾客,为其转述。"},{"q":"What did this experience teach Daniel about adulthood?","answer":"D","options":["That money is the only thing that matters.","That honesty is too much trouble.","That no one ever notices good behaviour.","That small honest choices shape who you become."],"explanation":"末段说成年也在于日常诚实的小选择塑造人格,为其概括。"}]'::jsonb, '[{"word":"integrity","cn":"正直"},{"word":"tempt","cn":"诱惑"},{"word":"wage","cn":"工资"}]'::jsonb, 2, 'elective2', 'U1', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U1', 'An Email about the Future', 'Dear George, Thanks for your birthday card! You asked whether I have been (1)____ much about the future now that I am seventeen. The answer is yes! Time seems to (2)____ so quickly. In just a year, I will be an (3)____. This time next year, I will be (4)____ my final school exams. With luck, I will (5)____ them all! Then, in a couple of years, I will be (6)____ at university. I think I will (7)____ law, because I have always wanted to help people. After I (8)____, I will look for a job in the courts. In the long (9)____, I hope that twenty years from now I will be working as a (10)____. Let''s see how things go!', 122, 2, '[{"q":"1","answer":"A","options":["thinking","eating","sleeping","driving"],"explanation":"been thinking about the future 一直在思考未来。"},{"q":"2","answer":"B","options":["stop","pass","fall","win"],"explanation":"time seems to pass quickly 时间过得飞快。"},{"q":"3","answer":"C","options":["animal","object","adult","error"],"explanation":"I will be an adult 我将成年。"},{"q":"4","answer":"D","options":["washing","growing","building","taking"],"explanation":"will be taking my final exams 正在参加期末考试。"},{"q":"5","answer":"A","options":["pass","lose","drop","miss"],"explanation":"pass them 通过考试。"},{"q":"6","answer":"B","options":["cooking","studying","sleeping","shopping"],"explanation":"will be studying at university 在大学读书。"},{"q":"7","answer":"C","options":["lose","sell","choose","throw"],"explanation":"I will choose law 我会选择法律。"},{"q":"8","answer":"D","options":["retire","resign","fail","graduate"],"explanation":"after I graduate 毕业以后。"},{"q":"9","answer":"A","options":["term","line","rope","road"],"explanation":"in the long term 从长远看。"},{"q":"10","answer":"B","options":["painter","judge","farmer","pilot"],"explanation":"working as a judge 当法官(与法律相关)。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U1', 'My First Part-time Job', 'Last summer I got my first part-time (1)____ at a busy café. On my first day I felt very (2)____, but my manager was kind and patient. My job was to (3)____ customers and clear the tables. The work was harder than I had (4)____, and by evening my feet really (5)____. At the end of the month, I received my first (6)____. Holding that money felt (7)____, because I had earned every cent myself. I soon learned to (8)____ my money carefully instead of (9)____ it all at once. That summer taught me that earning a wage also means learning to be (10)____ with what you have.', 108, 2, '[{"q":"1","answer":"C","options":["game","song","job","price"],"explanation":"a part-time job 一份兼职。"},{"q":"2","answer":"D","options":["asleep","golden","square","nervous"],"explanation":"felt very nervous 很紧张。"},{"q":"3","answer":"A","options":["serve","drop","hide","throw"],"explanation":"serve customers 招待顾客。"},{"q":"4","answer":"B","options":["eaten","expected","sold","slept"],"explanation":"harder than I had expected 比我预想的难。"},{"q":"5","answer":"C","options":["danced","cooked","hurt","drove"],"explanation":"my feet hurt 脚很疼。"},{"q":"6","answer":"D","options":["holiday","mistake","garden","wage"],"explanation":"my first wage 第一份工资。"},{"q":"7","answer":"A","options":["wonderful","boring","ugly","silent"],"explanation":"felt wonderful 感觉很棒。"},{"q":"8","answer":"B","options":["lose","manage","waste","drop"],"explanation":"manage my money carefully 谨慎管理钱。"},{"q":"9","answer":"C","options":["saving","earning","wasting","keeping"],"explanation":"instead of wasting it 而不是一下子挥霍。"},{"q":"10","answer":"D","options":["angry","asleep","famous","careful"],"explanation":"be careful with money 用钱要谨慎。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U1', 'My Driving Test Day', 'On the morning of my eighteenth birthday, I went to take my driving (1)____. I had been having lessons for months, yet I still felt (2)____. My instructor told me to stay (3)____ and trust my practice. As I sat (4)____ the wheel, my hands were shaking a little. I started the engine, checked my (5)____, and slowly pulled out onto the road. To my surprise, everything I had (6)____ came back to me. I remembered to (7)____ down at every corner and to watch for other cars. When the examiner finally said I had (8)____, I could hardly believe it. Driving, I realised, is not only a new (9)____ but also a serious duty, because I must protect my own life and the lives of (10)____ on the road.', 130, 2, '[{"q":"1","answer":"A","options":["test","song","meal","price"],"explanation":"a driving test 驾照考试。"},{"q":"2","answer":"B","options":["asleep","nervous","golden","empty"],"explanation":"felt nervous 紧张。"},{"q":"3","answer":"C","options":["loud","late","calm","busy"],"explanation":"stay calm 保持冷静。"},{"q":"4","answer":"D","options":["under","across","between","behind"],"explanation":"behind the wheel 在驾驶座上。"},{"q":"5","answer":"A","options":["mirrors","books","shoes","meals"],"explanation":"checked my mirrors 查看后视镜。"},{"q":"6","answer":"B","options":["eaten","learned","sold","lost"],"explanation":"everything I had learned 学过的一切。"},{"q":"7","answer":"C","options":["throw","sell","slow","cry"],"explanation":"slow down 减速。"},{"q":"8","answer":"D","options":["slept","danced","cooked","passed"],"explanation":"I had passed 我通过了。"},{"q":"9","answer":"A","options":["freedom","garden","machine","holiday"],"explanation":"a new freedom 一种新的自由。"},{"q":"10","answer":"B","options":["prices","others","machines","songs"],"explanation":"the lives of others 他人的生命。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U1', 'Living on My Own', 'After saving for two years, I finally moved into my own (1)____. It was small and far from the city centre, but at last it was truly (2)____. On the first night, I sat on the floor because I had no (3)____ yet. The room felt strangely (4)____ without my family around me. I had to learn to (5)____ my own meals, wash my own clothes, and pay every (6)____ on time. At first I made many small (7)____, like forgetting to buy milk or losing my keys. Slowly, though, I grew more (8)____. I began to enjoy the quiet and the sense of (9)____ that came with looking after myself. Living alone was not always easy, but it taught me more about growing up than any (10)____ ever had.', 130, 2, '[{"q":"1","answer":"C","options":["song","price","flat","error"],"explanation":"my own flat 自己的公寓。"},{"q":"2","answer":"D","options":["yours","his","theirs","mine"],"explanation":"it was mine 它属于我。"},{"q":"3","answer":"A","options":["furniture","weather","music","traffic"],"explanation":"no furniture 没有家具。"},{"q":"4","answer":"B","options":["golden","quiet","square","wooden"],"explanation":"strangely quiet 异常安静。"},{"q":"5","answer":"C","options":["sell","throw","cook","lose"],"explanation":"cook my own meals 自己做饭。"},{"q":"6","answer":"D","options":["song","game","prize","bill"],"explanation":"pay every bill 付清每张账单。"},{"q":"7","answer":"A","options":["mistakes","holidays","gardens","prizes"],"explanation":"made many mistakes 犯了不少错。"},{"q":"8","answer":"B","options":["asleep","independent","absent","ancient"],"explanation":"grew more independent 更加独立。"},{"q":"9","answer":"C","options":["hunger","danger","freedom","anger"],"explanation":"a sense of freedom 自由感。"},{"q":"10","answer":"D","options":["machine","garden","ticket","lesson"],"explanation":"than any lesson 比任何一课都多。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U1', 'A Memorable Graduation', 'I will never forget my graduation (1)____. After four years on the same campus, it was time to say (2)____. In the morning, we put on our gowns and (3)____ in the great hall. One by one, we walked across the (4)____ to receive our certificates. My parents sat in the audience, looking very (5)____ of me. When my name was (6)____, my heart beat fast and my eyes filled with tears. It was a (7)____ moment, both joyful and a little sad, because I knew my school days were (8)____. Afterwards we took photos and (9)____ to meet again in the future. As I left the campus for the last time, I felt ready to begin the next (10)____ of my life.', 123, 2, '[{"q":"1","answer":"A","options":["day","price","song","error"],"explanation":"my graduation day 毕业那天。"},{"q":"2","answer":"B","options":["money","goodbye","traffic","weather"],"explanation":"say goodbye 道别。"},{"q":"3","answer":"C","options":["slept","swam","gathered","drove"],"explanation":"gathered in the hall 在礼堂集合。"},{"q":"4","answer":"D","options":["ocean","forest","market","stage"],"explanation":"across the stage 走过舞台。"},{"q":"5","answer":"A","options":["proud","bored","angry","asleep"],"explanation":"proud of me 为我自豪。"},{"q":"6","answer":"B","options":["eaten","called","sold","washed"],"explanation":"my name was called 我的名字被念到。"},{"q":"7","answer":"C","options":["golden","square","bittersweet","empty"],"explanation":"a bittersweet moment 苦乐参半的时刻。"},{"q":"8","answer":"D","options":["kind","rich","calm","over"],"explanation":"my school days were over 校园生活结束了。"},{"q":"9","answer":"A","options":["promised","slept","cooked","drove"],"explanation":"promised to meet again 约定再见。"},{"q":"10","answer":"B","options":["garden","chapter","machine","ticket"],"explanation":"the next chapter of my life 人生的新篇章。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U1', 'Learning to Care', 'Turning eighteen changed the way I saw the world around me. I no longer wanted to be the (1)____ teenager I used to be, thinking only of myself. Instead, I began to feel a stronger sense of (2)____ for other people. One weekend, I decided to (3)____ at a local care home. At first I was nervous, but the elderly residents soon made me feel (4)____. I spent my afternoons reading to them and listening to their (5)____. Their experiences taught me lessons that no textbook could ever (6)____. I also signed up to give blood and even agreed to (7)____ an organ donation form. My parents were a little surprised, but in the end they (8)____ of my choice. Helping others, I discovered, did not make me feel smaller; it gave my life real (9)____. Growing up, I now believe, is mostly about learning to care beyond (10)____.', 149, 2, '[{"q":"1","answer":"C","options":["golden","sleepy","selfish","square"],"explanation":"the selfish teenager 自私的少年。"},{"q":"2","answer":"D","options":["weather","hunger","traffic","responsibility"],"explanation":"a sense of responsibility 责任感。"},{"q":"3","answer":"A","options":["volunteer","sleep","shop","drive"],"explanation":"volunteer at a care home 在养老院做志愿者。"},{"q":"4","answer":"B","options":["afraid","welcome","absent","asleep"],"explanation":"made me feel welcome 让我感到受欢迎。"},{"q":"5","answer":"C","options":["prices","machines","stories","tickets"],"explanation":"listening to their stories 听他们的故事。"},{"q":"6","answer":"D","options":["sell","lose","throw","teach"],"explanation":"no textbook could teach 课本教不了。"},{"q":"7","answer":"A","options":["sign","eat","drop","hide"],"explanation":"sign an organ donation form 签器官捐献表。"},{"q":"8","answer":"B","options":["slept","approved","cooked","swam"],"explanation":"they approved of my choice 他们赞成我的选择。"},{"q":"9","answer":"C","options":["traffic","weather","meaning","hunger"],"explanation":"real meaning 真正的意义。"},{"q":"10","answer":"D","options":["himself","yourself","themselves","myself"],"explanation":"care beyond myself 关心超越自我。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·对话 Looking Forward to Eighteen', '外研社版选择性必修第二册 U1 · dialogue', 3, 'Mia: My eighteenth birthday is next month. I really can''t wait!
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·短文 The Age of Majority', '外研社版选择性必修第二册 U1 · passage', 2, 'In most countries, turning eighteen marks the start of adulthood.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·对话 Leaving Home for the First Time', '外研社版选择性必修第二册 U1 · dialogue', 3, 'Hannah: I''m a bit worried about moving into the dormitory next week.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·短文 The Little Prince', '外研社版选择性必修第二册 U1 · passage', 2, 'The Little Prince was written by the French pilot Antoine de Saint-Exupéry.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·对话 My First Pay Day', '外研社版选择性必修第二册 U1 · dialogue', 3, 'Sam: Guess what? I got my first wage today!
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·短文 A Tip for Growing Up', '外研社版选择性必修第二册 U1 · passage', 2, 'Here is a simple tip for anyone who is growing up.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Write a Reply about Your Plans for the Future(写一封回信谈你对未来的计划)', 'My Plans for the Future', '假设你叫李华,你的笔友 Diana 来信问你对未来的打算。请用英语写一封约80词的回信,内容包括:① 一年后(成年时)你将会在做什么;② 几年后你打算在大学学什么;③ 长远来看你希望从事什么职业。注意:多用将来进行时(this time next year, I will be doing…),句子围绕中心、连贯自然。', 'Suppose you are Li Hua. Your pen-friend Diana has asked about your plans for the future. Write a reply (about 80 words) including: 1) what you will be doing in a year''s time, when you become an adult; 2) what you plan to study at university; 3) what job you hope to do in the long term. Try to use the future continuous (e.g. ''This time next year, I will be …'').', '["一年后的安排(In a year''s time, I will be …)","大学的打算(In a couple of years, I will be studying …)","长远的职业理想(In the long term, I hope I will be working as …)","多用将来进行时、句子连贯、围绕''未来计划''中心"]'::jsonb, 70, 100, 'Dear Diana, Thank you for your letter! You asked about my plans for the future, so here they are. This time next year, I will be an adult, and I will be taking my final school exams. With luck, I will pass them all. In a couple of years, I will be studying law at university, because I really want to help people. In the long term, I hope that one day I will be working as a judge. Let''s see how things go! Best wishes, Li Hua', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["This time next year, I will be an adult, and I will be taking my final school exams.","In a couple of years, I will be studying law at university.","In the long term, I hope that one day I will be working as a judge.","Let''s see how things go!"]'::jsonb, '[{"wrong":"This time next year, I will take my final exams.","correct":"This time next year, I will be taking my final exams.","note":"表将来某一时刻正在进行的动作,用 will be doing。"},{"wrong":"In a couple of years, I am studying at university.","correct":"In a couple of years, I will be studying at university.","note":"表将来正在进行,用 will be doing,而非现在进行时。"},{"wrong":"I hope I will working as a judge.","correct":"I hope I will be working as a judge.","note":"将来进行时结构是 will be + doing,不能省略 be。"}]'::jsonb, '【未来计划回信结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective2', 'U1', '{"title":"将来进行时 will be doing 速查","intro":"将来进行时 = will be + doing。核心含义:① 将来某一时刻\"正在进行\"的动作;② 委婉客观地询问对方安排;③ 顺理成章、按计划会发生的将来。判断口诀:看到 this time tomorrow / at 8 tonight / while you are… 等\"将来某点或同时\"标志,就用 will be doing。","table":{"headers":["用法","标志 / 例句"],"rows":[["将来某刻正在进行","this time tomorrow / at 8 tonight:I will be taking my exam this time tomorrow."],["与另一动作同时进行","while you are…:While you are sleeping, I will be travelling to work."],["委婉询问安排","Will you be doing…?:Will you be using the car tonight?"],["顺理成章的将来","…anyway / as usual:I will be seeing him tomorrow anyway."]]},"specialRules":[{"rule":"结构固定:will be + 现在分词(doing),be 不能省","mark":"will be working √ / will working ×"},{"rule":"强调那一刻\"正进行/持续\"用 will be doing;表\"一次性完成/承诺/决定\"用 will do","mark":"At 8 I will be having dinner(进行)/ I will pay you back(承诺)"},{"rule":"Will you be doing…? 比 Will you do…? 更客观礼貌,不带请求或施压","mark":"Will you be using it?(询问)/ Will you use it?(像请求)"},{"rule":"状态动词(know/like/be 等)一般不用进行时","mark":"I will know √ / I will be knowing ×"}],"why":["将来进行时把镜头对准\"将来的某一刻\",描述那一刻正在持续的画面;所以它常和精确的将来时间点或另一个同时发生的动作搭配,而一般将来时只是笼统地说\"将会做\"。"],"gaokaoPoints":["will be doing 与 will do 的辨析(进行/背景 vs 整体/完成):看有没有 this time tomorrow、at + 钟点、while 等标志。","Will you be doing…? 作委婉询问;I''ll be doing… 表顺理成章的将来,是语法填空与语境选择高频考点。"],"examVsReal":[{"exam":"This time tomorrow I will be flying to London.(考试)","real":"This time tomorrow I''ll be flying to London.","note":"口语里 will 常缩写成 ''ll,意思不变"},{"exam":"Will you be using the computer this evening?(考试·委婉)","real":"Are you going to use the computer tonight? / You using the computer later?","note":"日常口语也常用 be going to 或更随意的说法表达同样的询问"}]}'::jsonb, 'fltrp');
